-- Generated by the Quickshell shell (Settings > Appearance > Surfaces > Blur). Edit it there; changes here are overwritten.
hl.config({
    decoration = {
        blur = {
            enabled = true,
            size = 10,
            passes = 2,
            noise = 0.0117,
            contrast = 0.8916,
            brightness = 0.8,
            vibrancy = 0.5,
            vibrancy_darkness = 0.0,
            ignore_opacity = true,
            xray = false,
            new_optimizations = true,
            popups = false,
        },
    },
})

-- [rules]
hl.layer_rule({
    name = "island-blur",
    match = { namespace = "quickshell:island" },
    blur = true,
    ignore_alpha = 0.5,
})

hl.window_rule({
    name = "windows-no-blur",
    match = { class = ".*" },
    no_blur = false,
})
